import{_ as n,o as r,c as i,ah as s}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse(`{"title":"17. März: Wöginger schlägt zurück – Schmid-Aussage als 'Fiktion' bezeichnet","description":"8. Verhandlungstag in Linz: Wöginger bestreitet Druckausübung und Zeugen schildern das Gefühl, bei der Postenbesetzung 'unerwünscht' gewesen zu sein.","frontmatter":{"title":"17. März: Wöginger schlägt zurück – Schmid-Aussage als 'Fiktion' bezeichnet","description":"8. Verhandlungstag in Linz: Wöginger bestreitet Druckausübung und Zeugen schildern das Gefühl, bei der Postenbesetzung 'unerwünscht' gewesen zu sein.","date":"2026-03-17T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-17-woeginger-gegenangriff.md","filePath":"logbuch/2026-03-17-woeginger-gegenangriff.md"}`),t={name:"logbuch/2026-03-17-woeginger-gegenangriff.md"};function a(g,e,u,h,l,o){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="⚖️-17-marz-woginger-schlagt-zuruck-–-schmid-aussage-als-„fiktion-bezeichnet" tabindex="-1">⚖️ 17. März: Wöginger schlägt zurück – Schmid-Aussage als „Fiktion“ bezeichnet <a class="header-anchor" href="#⚖️-17-marz-woginger-schlagt-zuruck-–-schmid-aussage-als-„fiktion-bezeichnet" aria-label="Permalink to &quot;⚖️ 17. März: Wöginger schlägt zurück – Schmid-Aussage als „Fiktion“ bezeichnet&quot;">​</a></h1><p>Es ist <strong>Dienstag, der 17. März 2026 (18:02 Uhr)</strong>. Der achte Verhandlungstag am Landesgericht Linz markiert einen Wendepunkt in der Verteidigungsstrategie von August Wöginger.</p><h3 id="der-„burgersprechtag-euphemismus" tabindex="-1"><strong>Der „Bürgersprechtag“-Euphemismus</strong> <a class="header-anchor" href="#der-„burgersprechtag-euphemismus" aria-label="Permalink to &quot;**Der „Bürgersprechtag“-Euphemismus**&quot;">​</a></h3><p>Wöginger gab heute eine ausführliche Stellungnahme ab, in der er die Aussagen des Kronzeugen Thomas Schmid frontal angriff. Laut Wöginger habe er Schmid „nie einen Befehl gegeben“. Die Interventionen seien lediglich die Weiterleitung von Anliegen aus Bürgersprechtagen gewesen.</p><ul><li><strong>Wögingers Narrativ:</strong> Er sei nur der „Volksvertreter“, der sich für seine Bürger einsetzt.</li><li><strong>Die Anklage (WKStA):</strong> Sieht darin eine gezielte Anstiftung zum Amtsmissbrauch, um einen ÖVP-Bürgermeister auf den Posten des Finanzamt-Vorstands zu hieven.</li></ul><h3 id="das-gefuhl-des-„unerwunscht-seins" tabindex="-1"><strong>Das Gefühl des „Unerwünscht-Seins“</strong> <a class="header-anchor" href="#das-gefuhl-des-„unerwunscht-seins" aria-label="Permalink to &quot;**Das Gefühl des „Unerwünscht-Seins“**&quot;">​</a></h3><p>Besonders beklemmend waren heute die Aussagen der Mitbewerberinnen. Eine Zeugin schilderte, dass sie im Bewerbungsverfahren 2017 das deutliche Gefühl hatte, <strong>„unerwünscht“</strong> zu sein. Ein klassisches Element in unserem „System des Postenschachers“.</p><h3 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1"><strong>Bedeutung für das „Horten-Mysterium“</strong> <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;**Bedeutung für das „Horten-Mysterium“**&quot;">​</a></h3><p>Für unsere Mockumentary ist der heutige Tag eine Goldgrube für <strong>Teil 4: Die politische Liebesgeschichte</strong>:</p><ol><li><strong>Sprachanalyse:</strong> Wir werden den Begriff „Bürgersprechtag“ in unser „Pointillismus-Orakel“ aufnehmen. Es ist das perfekte Synonym für „Intervention“.</li><li><strong>Charakter-Entwicklung:</strong> Die scharfe Abgrenzung von Schmid zeigt die Risse im alten Machtgefüge.</li><li><strong>Die Ästhetik der Ablehnung:</strong> Das Zeugnis über das Gefühl, im eigenen Staat „unerwünscht“ zu sein, wird eine zentrale emotionale Note in Teil 4.</li></ol><hr><p><strong>„Wenn Macht sich als Bürgerservice tarnt, beginnt die Korruption, unsichtbar zu werden.“</strong></p><p>👉 <a href="/statistik.html">Die aktuellen Statistiken analysieren</a> 👉 <a href="/recherche/gericht-woeginger-braunau.html">Hintergrund: Der Fall Finanzamt Braunau</a></p><hr><p><em>Berichterstattung vom 17. März 2026. Der Countdown zum Urteil (21. April) läuft.</em></p>',15)])])}const m=n(t,[["render",a]]);export{c as __pageData,m as default};
